markers.CRABYARD:AUTH_TYPES:
export interface AuthStatus {
  authenticated: boolean;
  username: string | null;
  avatarUrl: string | null;
}

markers.CRABYARD:AUTH_COMMANDS:
export async function login(): Promise<string> {
  return invokeCommand("login");
}

export async function getAuthStatus(): Promise<AuthStatus> {
  return invokeCommand("get_auth_status");
}

export async function restoreAuth(): Promise<AuthStatus> {
  return invokeCommand("restore_auth");
}

export async function logout(): Promise<void> {
  return invokeCommand("logout");
}

markers.CRABYARD:COMMAND_TYPES:
login: [undefined, string];
  logout: [undefined, undefined];
  get_auth_status: [undefined, AuthStatus];
  restore_auth: [undefined, AuthStatus];
